// src/plugins/fontawesome.js
import { library } from '@fortawesome/fontawesome-svg-core'
import { FontAwesomeIcon } from '@fortawesome/vue-fontawesome'
import * as brandIcons from '@fortawesome/free-brands-svg-icons'
import * as solidIcons from '@fortawesome/free-solid-svg-icons'
import * as regularIcons from '@fortawesome/free-regular-svg-icons'

// Função auxiliar para filtrar apenas os ícones válidos
function extractIcons(icons) {
	return Object.keys(icons)
		.filter(key => key.startsWith('fa')) // Apenas ícones (ignora faPrefix, etc)
		.map(key => icons[key])
}

// Adiciona todos os ícones à biblioteca
library.add(
	...extractIcons(solidIcons),
	...extractIcons(regularIcons),
	...extractIcons(brandIcons)
)

export default FontAwesomeIcon
