<template>
    <header id="top-bar" :class="{ dark: isDark }" class="min-h-[6rem] flex items-center">
        <div class="container">
            <a class="navbar-brand" href="/">
                <img src="@/assets/logo2.png" alt="Logo G. Brandão" width="100" />
            </a>

            <!-- Botão Hambúrguer, só visível em mobile -->
            <button class="btn-hamburger" @click="toggleMenu" aria-label="Toggle Menu">
                <span :class="{ 'bar': true, 'open': menuOpen }"></span>
                <span :class="{ 'bar': true, 'open': menuOpen }"></span>
                <span :class="{ 'bar': true, 'open': menuOpen }"></span>
            </button>

            <nav :class="['nav', { open: menuOpen }]">
                <ul class="nav-list">
                    <li class="nav-item" :class="{ active: activeSection === 'home' }">
                        <a href="#home" @click.prevent="scrollToTop">{{ $t('topMenu.home') }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'skills' }">
                        <a href="#skills" @click="closeMenu">{{ $t('topMenu.skills') }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'projects' }">
                        <a href="#projects" @click="closeMenu">{{ $t('topMenu.projects') }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'experience' }">
                        <a href="#experienceTimeline" @click="closeMenu">{{ $t('topMenu.experience') }}</a>
                    </li>
                    <li class="nav-item" :class="{ active: activeSection === 'contact' }">
                        <a href="#contact" @click="closeMenu">{{ $t('topMenu.contact') }}</a>
                    </li>
                </ul>
                <div class="controls">
                    <button @click="toggleLanguage" class="btn-lang">
                        <font-awesome-icon icon="globe" /> {{ currentLang.toUpperCase() }}
                    </button>
                </div>
            </nav>
        </div>
    </header>
</template>


<script setup>
import { useI18n } from 'vue-i18n'
import { ref, onMounted, onBeforeUnmount, onUnmounted } from 'vue'

const isDark = ref(false)
const { locale } = useI18n()
const currentLang = ref(locale.value)

const menuOpen = ref(false)

function toggleLanguage() {
    currentLang.value = currentLang.value === 'pt' ? 'en' : 'pt'
    locale.value = currentLang.value
    localStorage.setItem('lang', currentLang.value)
}

const scrollToTop = () => {
    window.scrollTo({
        top: 0,
        behavior: 'smooth',
    })
    closeMenu()
}

const activeSection = ref('home')

const observeSections = () => {
    const options = {
        root: null,
        rootMargin: '0px',
        threshold: 0.6,
    }

    const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                activeSection.value = entry.target.id
            }
        })
    }, options)

    document.querySelectorAll('section').forEach((section) => {
        observer.observe(section)
    })

    return observer
}

let observer

const handleScroll = () => {
    const topBar = document.getElementById('top-bar')
    if (window.scrollY > 100) {
        topBar.classList.add('scrolled')
    } else {
        topBar.classList.remove('scrolled')
    }
}

const toggleMenu = () => {
    menuOpen.value = !menuOpen.value
}

const closeMenu = () => {
    menuOpen.value = false
}

onMounted(() => {
    const savedLang = localStorage.getItem('lang') || 'pt'
    locale.value = savedLang
    currentLang.value = savedLang
    observer = observeSections()

    const savedTheme = localStorage.getItem('theme')
    isDark.value = savedTheme === 'dark'
    if (isDark.value) {
        document.documentElement.classList.add('dark')
    } else {
        document.documentElement.classList.remove('dark')
    }
    window.addEventListener('scroll', handleScroll)
})

onBeforeUnmount(() => {
    window.removeEventListener('scroll', handleScroll)
})

onUnmounted(() => {
    if (observer) observer.disconnect()
})
</script>


<style scoped lang="scss">
@import '@/assets/sass/styles.scss';

#top-bar {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 1000;
    padding: 1rem 0;
    background-color: $dark-primary;
    backdrop-filter: blur(10px);
    transition: background-color 0.3s ease, backdrop-filter 0.3s ease;

    &.scrolled {
        background-color: rgba(28, 27, 26, 0.5);
    }

    .container {
        max-width: 1200px;
        margin: 0 auto;
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 0 1rem;
    }

    .navbar-brand img {
        max-width: 100px;
        height: auto;
    }

    /* Botão hamburguer - só no mobile */
    .btn-hamburger {
        display: none;
        flex-direction: column;
        justify-content: space-around;
        width: 28px;
        height: 22px;
        background: transparent;
        border: none;
        cursor: pointer;
        padding: 0;
        z-index: 1100;

        .bar {
            width: 100%;
            height: 3px;
            background-color: $dark-text-primary;
            border-radius: 2px;
            transition: all 0.3s ease;
            position: relative;
        }

        .bar.open:nth-child(1) {
            transform: rotate(45deg);
            top: 8px;
            position: relative;
        }

        .bar.open:nth-child(2) {
            opacity: 0;
        }

        .bar.open:nth-child(3) {
            transform: rotate(-45deg);
            top: -8px;
            position: relative;
        }
    }

    .nav {
        display: flex;
        align-items: center;
        gap: 3rem;

        .nav-list {
            display: flex;
            list-style: none;
            padding: 0;
            margin: 0;
            gap: 3rem;

            .nav-item {
                width: 85px;
                text-align: center;
                font-weight: 600;

                a {
                    display: block;
                    color: $dark-text-primary;
                    text-decoration: none;
                    font-weight: bold;
                    transition: color 0.3s ease;

                    &:hover {
                        color: $dark-secondary;
                        transition: color 0.2s ease;
                    }
                }

                &.active {
                    a {
                        color: $light-secondary;
                        border-bottom: 2px solid $light-secondary;
                    }
                }
            }
        }

        .controls {
            display: flex;
            gap: 3rem;

            .btn-lang,
            .btn-theme {
                background: none;
                border: none;
                color: $dark-text-primary;
                padding: 0.4rem 1rem;
                border-radius: 0.4rem;
                cursor: pointer;
                font-weight: bold;
                transition: all 0.3s ease;

                &:hover {
                    background-color: lighten($dark-button-hover, 10%);
                }
            }
        }
    }

    &.dark {
        background-color: #1a1a1a;
        transition: background-color 0.5s ease;

        .nav {
            .nav-list {
                .nav-item {
                    a {
                        color: #eee;
                        transition: color 0.3s ease;

                        &:hover {
                            color: $dark-secondary;
                            transition: color 0.2s ease;
                        }
                    }
                }
            }

            .controls {

                .btn-lang,
                .btn-theme {
                    border-color: #555;
                    color: #eee;
                    transition: all 0.3s ease;

                    &:hover {
                        background-color: darken($light-text-secondary, 30%);
                        transition: background-color 0.3s ease;
                    }
                }
            }
        }
    }

    /* ===== Responsividade ===== */
    @media (max-width: 768px) {
        padding: 0.5rem 0;

        .btn-hamburger {
            display: flex;
        }

        .nav {
            position: fixed;
            top: 6rem;
            right: 0;
            width: 240px;
            height: calc(100vh - 6rem);
            background-color: $dark-primary;
            backdrop-filter: blur(15px);
            flex-direction: column;
            gap: 1.5rem;
            padding: 1.5rem;
            box-shadow: -2px 0 12px rgba(0, 0, 0, 0.25);
            transform: translateX(100%);
            transition: transform 0.3s ease;
            z-index: 1050;

            &.open {
                transform: translateX(0);
            }

            .nav-list {
                flex-direction: column;
                gap: 1rem;

                .nav-item {
                    width: 100%;
                    text-align: left;

                    a {
                        padding: 0.5rem 1rem;
                        width: 100%;
                        display: block;
                    }
                }
            }

            .controls {
                justify-content: flex-start;
                gap: 1rem;

                .btn-lang,
                .btn-theme {
                    padding: 0.4rem 1rem;
                }
            }
        }
    }
}
</style>
