<template>
    <!--
        Section: Experience Timeline
        Description: Displays a vertical timeline of professional experiences, alternating left and right card alignment.
    -->
    <section id="experienceTimeline">
        <h2 class="section-title">{{ $t('experience.title') }}</h2>

        <!-- Timeline container -->
        <div class="relative mt-5">
            <div class="vertical-bar"></div>
            <div class="jobs-wrapper">
                <div v-for="(exp, index) in jobs" :key="index" class="job-item"
                    :class="index % 2 === 0 ? 'even' : 'odd'">
                    <div class="content">
                        <div class="card-experience">
                            <h3 class="fs-5 font-semibold">{{ exp.title }}</h3>
                            <p class="fs-6 text-[#E53935]">{{ exp.company }}</p>
                            <p class="fs-6 text-[#BDBDBD] mb-4">{{ exp.period }}</p>
                            <p class="fs-6 text-[#F5F5F5]" v-html="exp.description"></p>
                        </div>
                    </div>
                </div>
            </div>

        </div>
    </section>
</template>

<script setup>
/**
 * Imports the required methods for i18n and computed properties.
 */
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'

/**
 * Destructure locale and message retriever from Vue I18n.
 */
const { locale, getLocaleMessage } = useI18n()

/**
 * Computed property: jobs
 *
 * Retrieves the array of job experiences from the current locale messages.
 *
 * @returns {Array<Object>} List of job experience objects with keys: title, company, period, description
 */
const jobs = computed(() => {
    const messages = getLocaleMessage(locale.value)
    return messages.experience.jobs || []
})
</script>

<style scoped lang="scss">
@import '@/assets/sass/styles.scss';

#experienceTimeline {
    background-color: $dark-secondary;
    color: $dark-text-primary;
    padding: 10rem 10rem;

    .vertical-bar {
        position: absolute;
        left: 50%;
        transform: translateX(-50%);
        height: 100%;
        border-left: 2px solid $light-border;
    }

    .vertical-bar-divider {
        width: 1rem;
        height: 1rem;
        background-color: $dark-accent-red;
        border-radius: 9999px;
        border: 2px solid $dark-primary;
        position: absolute;
        left: 50%;
        transform: translateX(-50%);
        margin-top: 0.5rem;
    }

    .card-experience {
        background-color: $dark-primary;
        border: 1px solid $dark-border;
        padding: 1.5rem;
        border-radius: 1rem;
    }

    /* Container dos cards */
    .jobs-wrapper {
        position: relative;

        .job-item {
            margin-bottom: 1rem;
            position: relative;
            display: flex;
            align-items: flex-start;

            /* Lado padrão desktop (pares a esquerda, impares a direita) */
            &.even {
                flex-direction: row;
            }

            &.odd {
                flex-direction: row-reverse;
            }

            .content {
                width: 50%;
                padding: 0 2rem;
            }

            .divider {
                width: 2rem;
                position: relative;
                display: flex;
                justify-content: center;
            }
        }
    }
}

/* Responsividade para telas pequenas */
@media (max-width: 768px) {
    #experienceTimeline {
        padding: 4rem 2rem;

        .vertical-bar {
            display: none;
            /* Esconde linha vertical em mobile */
        }

        .jobs-wrapper {
            .job-item {
                flex-direction: column !important;
                /* Empilha os cards */

                .content {
                    width: 100%;
                    padding: 0 0 1.5rem 0;
                }

                .divider {
                    width: 100%;
                    height: 1rem;
                    position: relative;

                    &::before {
                        content: '';
                        position: absolute;
                        left: 50%;
                        top: 0;
                        transform: translateX(-50%);
                        width: 4px;
                        height: 100%;
                        background-color: $dark-accent-red;
                        border-radius: 2px;
                    }
                }
            }
        }
    }
}
</style>
